    82	
    83	    public Pedido obterPedido(Long id) {
    84	        return pedidoRepository.findById(id)
    85	            .orElseThrow(() -> new PedidoException("PEDIDO_NAO_ENCONTRADO", "Order not found", HttpStatus.NOT_FOUND));
    86	    }
    87	
    88	    @Transactional
    89	    public Pedido processarPagamento(Long pedidoId, String idTransacao, Instant pagoEm) {
    90	        Pedido pedido = obterPedido(pedidoId);
    91	
    92	
    93	        Optional<Pagamento> pagamentoExistente = pagamentoRepository.findByIdTransacao(idTransacao);
    94	        if (pagamentoExistente.isPresent()) {
    95	
    96	            return pedido;
    97	        }
    98	
    99	
   100	        if (!"AGUARDANDO_PAGAMENTO".equals(pedido.getSituacao())) {
   101	            throw new PedidoException("OPERACAO_NAO_PERMITIDA", "Payment already processed", HttpStatus.CONFLICT);
   102	        }
   103	
   104	
   105	        Instant agora = Instant.now();
   106	        long diffSegundos = java.time.temporal.ChronoUnit.SECONDS.between(pedido.getCriadoEm(), pagoEm);
   107	        if (diffSegundos > 48 * 3600) {
   108	
   109	            pedido.setSituacao("CANCELADO");
   110	            pedidoRepository.save(pedido);
   111	            avisoRepository.save(new Aviso(pedido.getCpfCliente(), "PEDIDO_CANCELADO", pedido.getId()));
   112	            throw new PedidoException("PEDIDO_EXPIRADO", "Payment expired", HttpStatus.CONFLICT);
   113	        }
   114	
   115	
   116	        verificarEstoque(pedido);
   117	
   118	
   119	        for (PedidoItem item : pedido.getItens()) {
   120	            Produto produto = produtoRepository.findById(item.getSku()).orElseThrow();
   121	            produto.setEstoque(produto.getEstoque() - item.getQuantidade());
   122	            produtoRepository.save(produto);
   123	        }
   124	
   125	
   126	        BigDecimal creditoProximaCompra = extrairCreditoDoResumo(pedido);
   127	        Optional<Cliente> cliente = clienteRepository.findByCpf(pedido.getCpfCliente());
   128	        if (cliente.isPresent()) {
   129	            Cliente c = cliente.get();
   130	            c.setSaldoCredito(c.getSaldoCredito().add(creditoProximaCompra));
   131	            clienteRepository.save(c);
   132	        }
   133	
   134	
   135	        Pagamento pagamento = new Pagamento(pedido.getId(), idTransacao, pagoEm);
   136	        pagamentoRepository.save(pagamento);
   137	
   138	
   139	        pedido.setSituacao("PAGO");
   140	        pedido.setIdTransacao(idTransacao);
   141	        Pedido pedidoAtualizado = pedidoRepository.save(pedido);
   142	
   143	
   144	        avisoRepository.save(new Aviso(pedido.getCpfCliente(), "PAGAMENTO_APROVADO", pedido.getId()));
   145	
   146	        return pedidoAtualizado;
   147	    }
   148	
   149	    @Transactional
   150	    public Pedido enviarPedido(Long pedidoId, String codigoRastreio) {
   151	        Pedido pedido = obterPedido(pedidoId);
   152	
   153	        if (!"PAGO".equals(pedido.getSituacao())) {
   154	            throw new PedidoException("OPERACAO_NAO_PERMITIDA", "Order must be paid", HttpStatus.CONFLICT);
   155	        }
   156	
   157	        pedido.setCodigoRastreio(codigoRastreio);
   158	        pedido.setSituacao("ENVIADO");
   159	
   160	        Pedido pedidoAtualizado = pedidoRepository.save(pedido);
   161	        avisoRepository.save(new Aviso(pedido.getCpfCliente(), "PEDIDO_ENVIADO", pedido.getId()));
   162	
   163	        return pedidoAtualizado;
   164	    }
   165	
   166	    @Transactional
   167	    public Pedido entregarPedido(Long pedidoId) {
   168	        Pedido pedido = obterPedido(pedidoId);
   169	
   170	        if (!"ENVIADO".equals(pedido.getSituacao())) {
   171	            throw new PedidoException("OPERACAO_NAO_PERMITIDA", "Order must be sent", HttpStatus.CONFLICT);
   172	        }
   173	
   174	        pedido.setSituacao("ENTREGUE");
   175	        return pedidoRepository.save(pedido);
   176	    }
   177	
   178	    @Transactional
   179	    public Pedido cancelarPedido(Long pedidoId) {
   180	        Pedido pedido = obterPedido(pedidoId);
   181	
   182	        if ("ENTREGUE".equals(pedido.getSituacao()) || "ENVIADO".equals(pedido.getSituacao())) {
   183	            throw new PedidoException("OPERACAO_NAO_PERMITIDA", "Cannot cancel sent/delivered order", HttpStatus.CONFLICT);
   184	        }
   185	
   186	
   187	        if ("PAGO".equals(pedido.getSituacao())) {
   188	
   189	            for (PedidoItem item : pedido.getItens()) {
   190	                Produto produto = produtoRepository.findById(item.getSku()).orElseThrow();
   191	                produto.setEstoque(produto.getEstoque() + item.getQuantidade());
   192	                produtoRepository.save(produto);
   193	            }
   194	
   195	
   196	            BigDecimal creditoProximaCompra = extrairCreditoDoResumo(pedido);
   197	            Optional<Cliente> cliente = clienteRepository.findByCpf(pedido.getCpfCliente());
   198	            if (cliente.isPresent()) {
   199	                Cliente c = cliente.get();
   200	                c.setSaldoCredito(c.getSaldoCredito().subtract(creditoProximaCompra));
   201	                if (c.getSaldoCredito().compareTo(BigDecimal.ZERO) < 0) {
   202	                    c.setSaldoCredito(BigDecimal.ZERO);
   203	                }
   204	                clienteRepository.save(c);
   205	            }
   206	        }
   207	
   208	        pedido.setSituacao("CANCELADO");
   209	        Pedido pedidoAtualizado = pedidoRepository.save(pedido);
   210	
   211	        avisoRepository.save(new Aviso(pedido.getCpfCliente(), "PEDIDO_CANCELADO", pedido.getId()));
   212	
   213	        return pedidoAtualizado;
   214	    }
   215	
   216	    private void verificarEstoque(Pedido pedido) {
   217	        for (PedidoItem item : pedido.getItens()) {
   218	            Produto produto = produtoRepository.findById(item.getSku()).orElseThrow();
   219	            if (produto.getEstoque() < item.getQuantidade()) {
   220	                pedido.setSituacao("CANCELADO");
   221	                pedidoRepository.save(pedido);
   222	                avisoRepository.save(new Aviso(pedido.getCpfCliente(), "PEDIDO_CANCELADO", pedido.getId()));
   223	                throw new PedidoException("ESTOQUE_INSUFICIENTE", "Insufficient stock", HttpStatus.CONFLICT);
   224	            }
   225	        }
   226	    }
   227	
   228	    private BigDecimal calcularPesoTotal(java.util.List<ItemDTO> itens) {
   229	        BigDecimal peso = BigDecimal.ZERO;
   230	        for (ItemDTO item : itens) {
   231	            Optional<Produto> produto = produtoRepository.findById(item.getSku());
   232	            if (produto.isPresent()) {
   233	                BigDecimal pesoUnitario = produto.get().getPesoKg();
   234	                BigDecimal quantidade = new BigDecimal(item.getQuantidade());
   235	                peso = peso.add(pesoUnitario.multiply(quantidade));
   236	            }
   237	        }
   238	        return peso;
   239	    }
   240	
   241	    private BigDecimal extrairCreditoDoResumo(Pedido pedido) {
   242	        try {
   243	            return new BigDecimal(pedido.getResumo().get("creditoProximaCompra").asText());
   244	        } catch (Exception e) {
   245	            return BigDecimal.ZERO;
   246	        }
   247	    }
   248	}
